question:
Which placement of a generic constraint is more flexible and idiomatic: constraining the whole type, or constraining only a specific extension?
```
// Option A
struct Pair<T: Comparable> {
    var first: T
    var second: T
}
// Option B
struct Pair<T> {
    var first: T
    var second: T
}
extension Pair where T: Comparable {
    func isOrdered() -> Bool { first <= second }
}
```
